function StripeImportButton({ order, onImport }) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleImport = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/stripe-session/${order.paymentId}`);
      const data = await res.json();
      if (!data.ok) { setError(data.error || "Ошибка Stripe"); setLoading(false); return; }
      if (!data.items || data.items.length === 0) { setError("Stripe вернул пустой список товаров"); setLoading(false); return; }
      await onImport(data.items);
      setLoading(false);
    } catch (e) {
      setError(e.message || "Ошибка сети");
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col gap-1.5">
      <button
        type="button"
        onClick={handleImport}
        disabled={loading}
        className="inline-flex items-center gap-2 rounded-lg bg-teal-600/80 hover:bg-teal-600 disabled:opacity-50 px-3 py-1.5 text-xs font-semibold text-white transition-colors"
      >
        {loading ? (
          <><span className="inline-block h-3 w-3 animate-spin rounded-full border-2 border-white/30 border-t-white" /> Загрузка из Stripe…</>
        ) : (
          <>⬇ Получить из Stripe</>
        )}
      </button>
      {error && <div className="text-red-300 text-[10px]">❌ {error}</div>}
    </div>
  );
}

