function PayPalButton({ createOrder, onApprove, onError, disabled, autoClickCard, billingCountryCode }) {
  const containerRef = useRef(null);
  const buttonsRef = useRef(null);
  const createOrderRef = useRef(createOrder);
  const onApproveRef = useRef(onApprove);
  const onErrorRef = useRef(onError);
  const [sdkStatus, setSdkStatus] = useState("loading"); // "loading" | "ready" | "error"
  createOrderRef.current = createOrder;
  onApproveRef.current = onApprove;
  onErrorRef.current = onError;

  // Watch for PayPal billing country <select> to appear and pre-fill from checkout form
  useEffect(() => {
    if (!billingCountryCode) return;

    const trySetCountry = () => {
      const selects = document.querySelectorAll("select");
      for (const sel of selects) {
        // Identify billing country select by checking if it has ISO-code options (LV, US, etc.)
        const hasCountryOptions =
          sel.querySelector('option[value="US"]') ||
          sel.querySelector('option[value="GB"]') ||
          sel.querySelector('option[value="DE"]');
        if (hasCountryOptions) {
          if (sel.value !== billingCountryCode) {
            sel.value = billingCountryCode;
            sel.dispatchEvent(new Event("change", { bubbles: true }));
            sel.dispatchEvent(new Event("input", { bubbles: true }));
          }
          return true;
        }
      }
      return false;
    };

    if (trySetCountry()) return;

    const observer = new MutationObserver(() => {
      if (trySetCountry()) observer.disconnect();
    });
    observer.observe(document.body, { childList: true, subtree: true });
    return () => observer.disconnect();
  }, [billingCountryCode, sdkStatus]);

  // Pre-click card button to warm up card form resources (desktop only)
  // On mobile, programmatic clicks on PayPal iframes can open the card modal
  // over the page while the user is still filling in their details.
  const isMobileDevice = /Mobi|Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
  useEffect(() => {
    if (!autoClickCard || isMobileDevice || sdkStatus !== "ready" || !containerRef.current) return;
    const timer = setTimeout(() => {
      if (!containerRef.current) return;
      const iframes = containerRef.current.querySelectorAll("iframe");
      // Card button is typically the last iframe (after PayPal yellow button)
      const cardIframe = Array.from(iframes).find(f =>
        (f.title || "").toLowerCase().includes("card") ||
        (f.title || "").toLowerCase().includes("credit") ||
        (f.title || "").toLowerCase().includes("debit")
      ) || iframes[iframes.length - 1];
      if (cardIframe) {
        cardIframe.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
      }
    }, 1200);
    return () => clearTimeout(timer);
  }, [autoClickCard, isMobileDevice, sdkStatus]);

  useEffect(() => {
    const clientId = import.meta.env.VITE_PAYPAL_CLIENT_ID;
    if (!clientId) { setSdkStatus("error"); return; }

    const mount = () => {
      if (!window.paypal || !containerRef.current) { setSdkStatus("error"); return; }
      if (buttonsRef.current) { try { buttonsRef.current.close(); } catch {} buttonsRef.current = null; }
      containerRef.current.innerHTML = "";
      const buttons = window.paypal.Buttons({
        style: { layout: "vertical", color: "gold", shape: "rect", label: "pay", height: 48 },
        createOrder: (...args) => createOrderRef.current(...args),
        onApprove: (...args) => onApproveRef.current(...args),
        onError: (err) => onErrorRef.current && onErrorRef.current(err),
      });
      buttonsRef.current = buttons;
      buttons.render(containerRef.current)
        .then(() => setSdkStatus("ready"))
        .catch((e) => { setSdkStatus("error"); console.error("PayPal render error:", e); });
    };

    if (window.paypal) {
      mount();
    } else {
      let script = document.getElementById("paypal-sdk");
      if (!script) {
        script = document.createElement("script");
        script.id = "paypal-sdk";
        script.src = `https://www.paypal.com/sdk/js?client-id=${clientId}&currency=USD&intent=capture&locale=en_US`;
        script.onerror = () => setSdkStatus("error");
        document.head.appendChild(script);
      }
      // Script may already be loaded (readyState complete) even if window.paypal just appeared
      if (window.paypal) {
        mount();
      } else {
        script.addEventListener("load", mount, { once: true });
        script.addEventListener("error", () => setSdkStatus("error"), { once: true });
      }
    }

    return () => {
      if (buttonsRef.current) { try { buttonsRef.current.close(); } catch {} buttonsRef.current = null; }
    };
  }, []);

  return (
    <div style={{ minHeight: 55 }}>
      {sdkStatus === "error" && (
        <div style={{ padding: "14px 16px", borderRadius: 14, background: "#fff3f3", border: "1px solid #fcc", color: "#c00", fontSize: 13, textAlign: "center" }}>
          PayPal could not load. Please refresh or try another payment method.
        </div>
      )}
      <div ref={containerRef} style={{ visibility: sdkStatus === "ready" ? "visible" : "hidden", minHeight: sdkStatus === "ready" ? undefined : 55 }} />
    </div>
  );
}

