function HeroSavingsTicker({ className = "" }) {
  const FROM = 400;
  const TO = 75;
  const [value, setValue] = useState(FROM);
  const [pulse, setPulse] = useState(false);
  const [eased, setEased] = useState(0);
  const [linear, setLinear] = useState(0);
  const rafRef = useRef(null);
  const timeoutRef = useRef(null);

  useEffect(() => {
    let cancelled = false;
    const runCycle = () => {
      setValue(FROM);
      setEased(0);
      setLinear(0);
      timeoutRef.current = setTimeout(() => {
        if (cancelled) return;
        const start = performance.now();
        const duration = 1700;
        const step = (now) => {
          if (cancelled) return;
          const p = Math.min(1, (now - start) / duration);
          const e = 1 - Math.pow(1 - p, 3);
          setValue(Math.round(FROM - (FROM - TO) * e));
          setEased(e);
          setLinear(p);
          if (p < 1) {
            rafRef.current = requestAnimationFrame(step);
          } else {
            setPulse(true);
            setTimeout(() => setPulse(false), 500);
            timeoutRef.current = setTimeout(() => {
              if (cancelled) return;
              runCycle();
            }, 1200);
          }
        };
        rafRef.current = requestAnimationFrame(step);
      }, 300);
    };
    runCycle();
    return () => {
      cancelled = true;
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const colorStops = [
    { t: 0, h: 0, s: 92, l: 58 },
    { t: 0.16, h: 14, s: 94, l: 55 },
    { t: 0.32, h: 30, s: 96, l: 52 },
    { t: 0.48, h: 45, s: 96, l: 50 },
    { t: 0.62, h: 62, s: 90, l: 48 },
    { t: 0.78, h: 95, s: 78, l: 46 },
    { t: 0.9, h: 140, s: 75, l: 52 },
    { t: 1, h: 152, s: 78, l: 56 },
  ];
  let a = colorStops[0];
  let b = colorStops[colorStops.length - 1];
  for (let i = 0; i < colorStops.length - 1; i++) {
    if (linear >= colorStops[i].t && linear <= colorStops[i + 1].t) {
      a = colorStops[i];
      b = colorStops[i + 1];
      break;
    }
  }
  const span = b.t - a.t || 1;
  const localT = Math.min(1, Math.max(0, (linear - a.t) / span));
  const hue = a.h + (b.h - a.h) * localT;
  const sat = a.s + (b.s - a.s) * localT;
  const light = a.l + (b.l - a.l) * localT;
  const color = `hsl(${hue.toFixed(1)}, ${sat.toFixed(1)}%, ${light.toFixed(1)}%)`;

  return (
    <span className={`inline-flex items-baseline align-middle ${className}`}>
      <span
        className={`text-[16px] font-black tabular-nums transition-transform md:text-2xl ${pulse ? "scale-110" : "scale-100"}`}
        style={{ color, transition: "transform 0.35s cubic-bezier(0.34,1.56,0.64,1)", textShadow: "1px 2px 0 rgba(0,0,0,0.275), 2px 4px 0 rgba(0,0,0,0.225), 3px 6px 0 rgba(0,0,0,0.175), 4px 8px 0 rgba(0,0,0,0.125), 6px 12px 10px rgba(0,0,0,0.15)" }}
      >
        ${value}
      </span>
    </span>
  );
}

