function TrackOrderPage({ t, supabase, currentUser }) {
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [notFound, setNotFound] = useState(false);
  const [accessMessage, setAccessMessage] = useState("");
  const [trackInput, setTrackInput] = useState("");
  const [trackUrl, setTrackUrl] = useState("");

  function handleTrack(e) {
    e.preventDefault();
    const num = trackInput.trim();
    if (!num) return;
    setTrackUrl(num);
  }

  async function handleCheck(e) {
    e.preventDefault();
    const query = input.trim().toUpperCase();
    if (!query) return;
    const ownerEmail = currentUser?.email?.trim().toLowerCase();
    if (!ownerEmail) {
      setResult(null);
      setNotFound(false);
      setAccessMessage(t("trackOrderSignInRequired"));
      return;
    }
    setLoading(true);
    setResult(null);
    setNotFound(false);
    setAccessMessage("");
    try {
      const { data, error } = await supabase
        .from("orders")
        .select("*")
        .ilike("id", query)
        .eq("email", ownerEmail)
        .limit(1);
      if (error) throw error;
      if (!data || data.length === 0) {
        setNotFound(true);
      } else {
        const row = data[0];
        const meta = row.metadata && typeof row.metadata === "object" ? row.metadata : {};
        setResult({
          id: row.id,
          status: row.status || meta.status || "pending",
          createdAt: meta.createdAt || row.created_at || "",
          total: meta.total ?? row.total ?? 0,
          subtotal: meta.subtotal ?? row.subtotal ?? 0,
          shipping: meta.shipping ?? row.shipping ?? 0,
          shippingType: meta.shippingType || row.shipping_type || "",
          automaticDiscount: meta.automaticDiscount ?? row.automatic_discount ?? 0,
          promoDiscount: meta.promoDiscount ?? row.promo_discount ?? 0,
          affiliateDiscount: meta.affiliateDiscount ?? row.affiliate_discount ?? 0,
          affiliateCode: meta.affiliateCode || row.affiliate_code || "",
          paypalFee: meta.paypalFee ?? 0,
          items: meta.items || row.items || [],
          paymentProvider: row.payment_provider || meta.paymentProvider || "",
          trackingNumber: row.tracking_number || meta.trackingNumber || meta.tracking_number || "",
          trackingNumber2: row.tracking_number_2 || meta.trackingNumber2 || meta.tracking_number_2 || "",
        });
      }
    } catch {
      setNotFound(true);
    } finally {
      setLoading(false);
    }
  }

  const isPaid = result && (result.status === "paid" || result.status === "completed");

  return (
    <main className="mx-auto max-w-2xl px-4 pt-8 pb-16 md:px-6 md:pt-14 space-y-6 overflow-x-hidden">
      <TrackingCardFrame type="order">
        <h1 className="mb-5 text-center text-xl font-semibold uppercase tracking-[0.12em] text-white sm:text-left md:text-2xl">
          {t("trackOrderTitle")}
        </h1>
        <form onSubmit={handleCheck} className="flex flex-col gap-3 sm:flex-row">
          <input
            type="text"
            value={input}
            onChange={(e) => { setInput(e.target.value); setResult(null); setNotFound(false); setAccessMessage(""); }}
            placeholder={t("trackOrderPlaceholder")}
            className="flex-1 rounded-full border border-white/20 bg-white/10 px-5 py-3 text-[14px] font-semibold uppercase tracking-[0.06em] text-white placeholder:text-white/50 outline-none focus:border-white/50"
            autoComplete="off"
            spellCheck={false}
          />
          <button
            type="submit"
            disabled={loading || !input.trim()}
            className="rounded-full bg-black px-6 py-3 text-[13px] font-bold uppercase tracking-[0.18em] text-white transition hover:bg-black/70 disabled:opacity-50"
          >
            {loading ? t("trackOrderChecking") : t("trackOrderBtn")}
          </button>
        </form>

        {accessMessage && (
          <p className="mt-6 text-center text-[14px] font-semibold text-white/60">
            {accessMessage}
          </p>
        )}

        {notFound && (
          <p className="mt-6 text-center text-[14px] font-semibold text-white/60 uppercase tracking-wide">
            {t("trackOrderNotFound")}
          </p>
        )}

        {result && (
          <div className="mt-8 rounded-[1rem] border border-white/15 bg-white/5 p-5 md:p-7">
            <div className="flex items-center justify-between gap-3 flex-wrap">
              <span className="text-[13px] font-bold uppercase tracking-[0.14em] text-white/60">
                {t("trackOrderId")}
              </span>
              <span className="font-mono text-[15px] font-bold tracking-widest text-white">{result.id}</span>
            </div>

            <div className="mt-3 flex items-center justify-between gap-3 flex-wrap">
              <span className="text-[13px] font-bold uppercase tracking-[0.14em] text-white/60">Status</span>
              <span className={`rounded-full px-4 py-1 text-[12px] font-bold uppercase tracking-[0.16em] ${isPaid ? "bg-green-500/20 text-green-300" : "bg-yellow-500/20 text-yellow-300"}`}>
                {isPaid ? t("trackOrderPaid") : t("trackOrderPending")}
              </span>
            </div>

            {result.createdAt && (
              <div className="mt-3 flex items-center justify-between gap-3 flex-wrap">
                <span className="text-[13px] font-bold uppercase tracking-[0.14em] text-white/60">{t("trackOrderDate")}</span>
                <span className="text-[14px] text-white">
                  {new Date(result.createdAt).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" })}
                </span>
              </div>
            )}

            {result.total > 0 && (
              <div className="mt-3 flex items-center justify-between gap-3 flex-wrap">
                <span className="text-[13px] font-bold uppercase tracking-[0.14em] text-white/60">{t("trackOrderTotal")}</span>
                <span className="text-[14px] font-semibold text-white">${Number(result.total).toFixed(2)}</span>
              </div>
            )}

            {result.paymentProvider && result.paymentProvider !== "pending" && (
              <div className="mt-3 flex items-center justify-between gap-3 flex-wrap">
                <span className="text-[13px] font-bold uppercase tracking-[0.14em] text-white/60">{t("trackOrderMethod")}</span>
                <span className="text-[14px] text-white">{publicPaymentMethod(result.paymentProvider)}</span>
              </div>
            )}

            {result.trackingNumber || result.trackingNumber2 ? (
              <>
                {result.trackingNumber && (
                  <CopyTrackingNumber
                    trackingNumber={result.trackingNumber}
                    label={result.trackingNumber2 ? "Tracking #1 — Tap to copy" : "Tracking Number — Tap to copy"}
                  />
                )}
                {result.trackingNumber2 && (
                  <CopyTrackingNumber
                    trackingNumber={result.trackingNumber2}
                    label={result.trackingNumber ? "Tracking #2 — Tap to copy" : "Tracking Number — Tap to copy"}
                  />
                )}
              </>
            ) : (
              <div className="mt-3 flex items-center justify-between gap-3 flex-wrap">
                <span className="text-[13px] font-bold uppercase tracking-[0.14em] text-white/60">Tracking Number</span>
                <span className="text-[13px] text-white italic">Tracking number pending</span>
              </div>
            )}

            {Array.isArray(result.items) && result.items.length > 0 && (
              <div className="mt-5 border-t border-white/10 pt-4">
                <p className="mb-3 text-[13px] font-bold uppercase tracking-[0.14em] text-white/60">{t("trackOrderItems")}</p>
                <ul className="space-y-2">
                  {result.items.map((item, i) => (
                    <li key={i} className="flex items-center justify-between text-[14px] text-white">
                      <span>{publicProductName(item.name)} {String(item.dose || "").replace(/ each$/i, "")} × {item.quantity}</span>
                      {item.price && <span className="text-white/70">${(item.price * item.quantity).toFixed(2)}</span>}
                    </li>
                  ))}
                </ul>

                <div className="mt-4 border-t border-white/10 pt-4 space-y-2">
                  {result.subtotal > 0 && (
                    <div className="flex justify-between text-[13px] text-white/70">
                      <span>Subtotal</span>
                      <span>${Number(result.subtotal).toFixed(2)}</span>
                    </div>
                  )}
                  {result.automaticDiscount > 0 && (
                    <div className="flex justify-between text-[13px] text-white/70">
                      <span>Automatic discount</span>
                      <span className="text-green-400">-${Number(result.automaticDiscount).toFixed(2)}</span>
                    </div>
                  )}
                  {result.promoDiscount > 0 && (
                    <div className="flex justify-between text-[13px] text-white/70">
                      <span>Promo discount</span>
                      <span className="text-green-400">-${Number(result.promoDiscount).toFixed(2)}</span>
                    </div>
                  )}
                  {result.affiliateDiscount > 0 && (
                    <div className="flex justify-between text-[13px] text-white/70">
                      <span>Affiliate discount{result.affiliateCode ? ` (${result.affiliateCode})` : ""}</span>
                      <span className="text-green-400">-${Number(result.affiliateDiscount).toFixed(2)}</span>
                    </div>
                  )}
                  <div className="flex justify-between text-[13px] text-white/70">
                    <span>Shipping</span>
                    <span>{result.shipping > 0 ? `$${Number(result.shipping).toFixed(2)}` : "FREE"}</span>
                  </div>
                  {result.paypalFee > 0 && (
                    <div className="flex justify-between text-[13px] text-white/70">
                      <span>PayPal fee (4.9%)</span>
                      <span className="text-amber-300">+${Number(result.paypalFee).toFixed(2)}</span>
                    </div>
                  )}
                  <div className="flex justify-between text-[14px] font-bold text-white border-t border-white/10 pt-2">
                    <span>Total</span>
                    <span>${Number(result.total).toFixed(2)}</span>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </TrackingCardFrame>

      {/* ── TRACK YOUR SHIPMENT (17track embed) ── */}
      <TrackingCardFrame type="17track">
        <h1 className="mb-5 text-center font-semibold uppercase tracking-[0.12em] text-white sm:text-left" style={{fontSize:"clamp(1rem,4vw,1.5rem)"}}>
          Track Your Order (17TRACK)
        </h1>
        <form onSubmit={handleTrack} className="flex flex-col gap-3 sm:flex-row">
          <input
            type="text"
            value={trackInput}
            onChange={(e) => { setTrackInput(e.target.value); setTrackUrl(""); }}
            placeholder="Enter tracking number (e.g. GLY60503213136SZ)"
            className="flex-1 rounded-full border border-white/20 bg-white/10 px-5 py-3 text-[14px] font-semibold uppercase tracking-[0.06em] text-white placeholder:text-white/50 outline-none focus:border-white/50"
            autoComplete="off"
            spellCheck={false}
          />
          <button
            type="submit"
            disabled={!trackInput.trim()}
            className="rounded-full bg-black px-6 py-3 text-[13px] font-bold uppercase tracking-[0.18em] text-white transition hover:bg-black/70 disabled:opacity-50"
          >
            Track
          </button>
        </form>

        {trackUrl && (
          <div className="mt-6">
            <div className="rounded-xl border border-white/10 overflow-y-auto overflow-x-hidden" style={{height: "820px"}}>
              <iframe
                key={trackUrl}
                src={`https://t.17track.net/en?lang=en#nums=${encodeURIComponent(trackUrl)}`}
                className="border-0 block"
                style={{height: "1400px", width: "100%", minWidth: 0, maxWidth: "100%"}}
                title="Track Shipment"
                allow="clipboard-write"
              />
            </div>
            <div className="mt-3 text-center">
              <a
                href={`https://t.17track.net/en#nums=${encodeURIComponent(trackUrl)}`}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-2 rounded-full border border-white/20 bg-white/10 px-5 py-2 text-[13px] font-semibold uppercase tracking-[0.12em] text-white/80 transition hover:bg-white/20"
              >
                Open on 17track
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>
                  <polyline points="15 3 21 3 21 9"/>
                  <line x1="10" y1="14" x2="21" y2="3"/>
                </svg>
              </a>
            </div>
          </div>
        )}
      </TrackingCardFrame>

      {/* ── TRACK YOUR ORDER (FedEx) ── */}
      <FedExTrackBlock />

      {/* ── TRACK YOUR ORDER (USPS) ── */}
      <USPSTrackBlock />

      {/* ── TRACK YOUR ORDER (UPS) ── */}
      <UPSTrackBlock />
    </main>
  );
}

function ContactPage({ copySupportEmail, copiedEmail, t, language, onNewMessage }) {
  const socialLinks = [
    {
      name: "X",
      icon: SOCIAL_ICONS.X,
      url: "https://x.com/10BottleValueCo",
      sub: "1200+ followers",
    },
    {
      name: "Trustpilot",
      icon: SOCIAL_ICONS.Trustpilot,
      url: "https://www.trustpilot.com/review/10bottlevalue.co",
      rating: { score: 4.6, count: 23 },
    },
  ];
  const socialCardClassName =
    "group relative z-20 flex min-h-[190px] w-full flex-col items-center justify-center rounded-[1.25rem] border border-white/15 bg-black/65 px-5 py-5 shadow-[0_10px_28px_rgba(0,0,0,0.32)] transition duration-300 hover:border-white/25 hover:bg-black/75";

  return (
    <main className="mx-auto max-w-7xl px-4 pt-4 pb-8 md:px-10 md:pt-14 md:pb-20">
      <section className="rounded-[1.6rem] border border-white/20 bg-black/40 px-5 py-10 text-center shadow-[0_10px_30px_rgba(0,0,0,0.06)] md:rounded-[2.5rem] md:px-12 md:py-14">
        <h1 className="mt-3 text-3xl font-semibold uppercase tracking-[0.12em] text-white md:mt-5 md:text-5xl">
          {t("getInTouch")}
        </h1>

        <p className="mx-auto mt-6 max-w-2xl text-[12px] leading-7 tracking-[0.18em] uppercase text-white/80 md:text-[13px]">
          {language === "RU"
            ? "По вопросам заказов, продуктов, партнёрской программы или общим вопросам свяжитесь с нами напрямую по email."
            : language === "UA"
            ? "З питань замовлень, продуктів, партнерської програми або загальних запитів звʼяжіться з нами напряму через email."
            : language === "DE"
            ? "Bei Fragen zu Bestellungen, Produkten, Affiliate-Anfragen oder allgemeinen Anliegen kontaktieren Sie uns direkt per E-Mail."
            : language === "ES"
            ? "Para soporte de pedidos, preguntas sobre productos, solicitudes de afiliado o consultas generales, contactenos directamente por email."
            : "For order support, product questions, affiliate requests, or general inquiries, contact us directly by email."}
        </p>

        <div className="mx-auto mt-8 max-w-xl rounded-[1.5rem] border border-white/20 bg-black/40 px-5 py-6 shadow-[0_14px_35px_rgba(0,0,0,0.12)] md:mt-10 md:rounded-[2rem] md:px-7 md:py-8">
          <div className="text-[11px] font-semibold uppercase tracking-[0.3em] text-white">
            {t("emailSupport")}
          </div>
          <a
            href="mailto:support@10bottlevalue.co"
            className="mt-4 block w-full text-center text-[14px] font-semibold uppercase tracking-[0.12em] text-white transition hover:text-white sm:text-[18px] md:text-[24px]"
          >
            SUPPORT@10BOTTLEVALUE.CO
          </a>
          <div className="mx-auto mt-6 h-px w-20 bg-white/30" />
          <div className="mt-6 text-[12px] uppercase tracking-[0.22em] text-white">
            {t("responseTime")}
          </div>
          <div className="mt-2 text-[11px] text-white tracking-wide uppercase">
            {t("responseTimeGuarantee")}
          </div>
          {onNewMessage && (
            <button
              type="button"
              onClick={onNewMessage}
              className="mt-4 inline-flex items-center gap-2 rounded-full bg-white px-8 py-3 text-[12px] font-black uppercase tracking-[0.22em] text-black transition hover:bg-white/90 active:scale-[0.97]"
            >
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <rect x="2" y="4" width="20" height="16" rx="2"/><path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7"/>
              </svg>
              New Message
            </button>
          )}
        </div>
      </section>

      <section className="mt-2 px-5 py-10 text-center md:mt-5 md:px-0 md:py-14">
        <h2 className="text-[18px] uppercase tracking-[0.28em] text-white/80 md:text-[28px]">
          {language === "RU"
            ? "НАШИ СОЦИАЛЬНЫЕ КАНАЛЫ"
            : language === "UA"
            ? "НАШІ СОЦІАЛЬНІ КАНАЛИ"
            : language === "DE"
            ? "Unsere Social-Media-Kanäle"
            : language === "ES"
            ? "Nuestros canales sociales"
            : "Our Social Channels"}
        </h2>

        <div className="mx-auto mt-8 grid w-full max-w-[1180px] grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3 md:mt-14">
          {socialLinks.map((item) => {
            const inner = (
              <>
                <div className={`flex h-14 w-14 items-center justify-center rounded-full bg-white/10 shadow-[0_14px_30px_rgba(0,0,0,0.12)] transition-all duration-300 ${item.disabled ? "opacity-40" : "group-hover:bg-white/20 group-hover:scale-110"}`}>
                  {SOCIAL_ICONS[item.name] || item.icon}
                </div>
                <div className={`mt-3 text-[11px] uppercase tracking-[0.2em] transition ${item.disabled ? "text-white/40" : "text-white/80 group-hover:text-white"}`}>
                  {item.name === "X" ? "X (Twitter)" : item.name}
                </div>
                {item.rating && (
                  <div className="mt-2 flex flex-col items-center gap-1">
                    <div className="flex items-center gap-[3px]">
                      {[1,2,3,4].map(i => (
                        <div key={i} className="flex h-5 w-5 items-center justify-center rounded-[3px]" style={{background:"#00b67a"}}>
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="white">
                            <path d="M12 2l2.9 8.7H23l-7.4 5.4 2.8 8.6L12 19.4l-6.4 5.3 2.8-8.6L2 10.7h8.1z"/>
                          </svg>
                        </div>
                      ))}
                      <div className="relative flex h-5 w-5 items-center justify-center overflow-hidden rounded-[3px]">
                        <div className="absolute inset-0 flex">
                          <div className="h-full w-1/2" style={{background:"#00b67a"}}/>
                          <div className="h-full w-1/2" style={{background:"#dcdce6"}}/>
                        </div>
                        <svg className="relative z-10" width="12" height="12" viewBox="0 0 24 24" fill="white">
                          <path d="M12 2l2.9 8.7H23l-7.4 5.4 2.8 8.6L12 19.4l-6.4 5.3 2.8-8.6L2 10.7h8.1z"/>
                        </svg>
                      </div>
                    </div>
                    <div className="text-[10px] font-semibold tracking-wide text-white">{item.rating.score} <span className="font-normal text-white">· {item.rating.count} {language === "RU" ? "отзывов" : language === "UA" ? "відгуків" : language === "DE" ? "Bewertungen" : language === "ES" ? "reseñas" : "reviews"}</span></div>
                  </div>
                )}
                {item.sub && (
                  <div className="mt-2 text-[10px] uppercase tracking-wide text-white">
                    {item.sub}
                  </div>
                )}
                <div className="mt-3 inline-flex items-center gap-1.5 rounded-full border border-white/25 px-3 py-1.5 text-[8px] font-bold uppercase tracking-[0.16em] text-white/90 transition group-hover:border-white/45 group-hover:bg-white/5">
                  {item.name === "Trustpilot"
                    ? language === "RU" ? "Читать отзывы" : language === "UA" ? "Читати відгуки" : language === "DE" ? "Bewertungen lesen" : language === "ES" ? "Leer reseñas" : "Read reviews"
                    : language === "RU" ? "Подписаться" : language === "UA" ? "Підписатися" : language === "DE" ? "Folgen" : language === "ES" ? "Seguir" : "Follow us"}
                  <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M5 12h14"/><path d="m12 5 7 7-7 7"/>
                  </svg>
                </div>
              </>
            );
            return item.disabled ? (
              <div key={item.name} className={`${socialCardClassName} cursor-not-allowed opacity-50`} aria-label={item.name}>
                {inner}
              </div>
            ) : (
              <a key={item.name} href={item.url} target="_blank" rel="noopener noreferrer" className={`${socialCardClassName} cursor-pointer`} aria-label={item.name}>
                {inner}
              </a>
            );
          })}
          <div
            data-testid="card-peptigrity"
            className={`${socialCardClassName} cursor-default`}
          >
            <PeptigrityMark />
            <div className="mt-3 text-[11px] uppercase tracking-[0.2em] text-white/80">
              Peptigrity
            </div>
            <a
              href="https://peptigrity.com/add/review?shopId=279"
              target="_blank"
              rel="noopener noreferrer"
              data-testid="link-peptigrity-review"
              className="mt-3 inline-flex min-h-[34px] items-center gap-2 rounded-full border border-white/25 px-4 py-2 text-[8px] font-bold uppercase tracking-[0.12em] text-white/90 transition hover:border-white/45 hover:bg-white/5"
            >
              REVIEW US ON PEPTERGITY
              <ArrowRight size={11} aria-hidden="true" />
            </a>
          </div>
        </div>
      </section>
    </main>
  );
}

