  function normalizeEmail(value) {
    return String(value || "").trim().toLowerCase();
  }

  const ADMIN_EMAILS = ["support@10bottlevalue.co"];

  function isAdminUser(user = currentUser) {
    return ADMIN_EMAILS.includes(normalizeEmail(user?.email));
  }

  function stripQuoteMarker(text) {
    return String(text || "").replace(/^\[QUOTE:([^\]]*)\]/, "").trim();
  }

  function extractQuoteSnippet(text) {
    const m = String(text || "").match(/^\[QUOTE:([^\]]*)\]/);
    if (!m) return null;
    let raw;
    try { raw = decodeURIComponent(m[1]); } catch { raw = m[1]; }
    try {
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed === "object" && "text" in parsed) return parsed;
    } catch {}
    return { id: null, side: null, text: raw }; // backward-compat: older quotes stored plain text only
  }

  function makeQuoteSnippet(text, id, side) {
    const clean = stripQuoteMarker(text)
      .replace(/\[IMAGE:[^\]]+\]/g, "📷 Photo")
      .replace(/\[VIDEO:[^\]]+\]/g, "🎥 Video")
      .replace(/\[FILE:[^\]]+\]/g, "📄 File")
      .trim();
    const snippet = clean.length > 120 ? clean.slice(0, 120) + "…" : clean;
    return { id: id ?? null, side: side ?? null, text: snippet };
  }

  function chatMsgDomId(id, side) {
    return `chatmsg-${side}-${id}`;
  }

  function jumpToChatMsg(id, side) {
    if (id == null || !side) return;
    const key = chatMsgDomId(id, side);
    const el = document.getElementById(key);
    if (!el) return;
    const scrollContainer = inboxScrollRef.current;
    if (scrollContainer?.contains(el)) {
      const containerRect = scrollContainer.getBoundingClientRect();
      const targetRect = el.getBoundingClientRect();
      const centeredTop = scrollContainer.scrollTop
        + targetRect.top
        - containerRect.top
        - (scrollContainer.clientHeight - targetRect.height) / 2;
      scrollContainer.scrollTo({ top: centeredTop, behavior: "smooth" });
    } else {
      el.scrollIntoView({ behavior: "smooth", block: "center" });
    }
    setHighlightedMsgKey(key);
    clearTimeout(window.__tbvHighlightTimeout);
    window.__tbvHighlightTimeout = setTimeout(() => setHighlightedMsgKey(null), 1600);
  }

  function getChatAttachmentReferences(text) {
    const references = [];
    if (typeof text !== "string") return references;
    const tagPattern =
      /\[(?:IMAGE|VIDEO):([^\]]+)\]|\[FILE:(.+):([^\]]*)\]/g;
    for (const match of text.matchAll(tagPattern)) {
      const reference = match[1] || match[2];
      if (reference) references.push(reference);
    }
    return references;
  }

  const chatAttachmentRequestKey = useMemo(() => {
    const requestItems = [];
    const seen = new Set();
    for (const message of [...userInboxMessages, ...adminMessages]) {
      const messageId = Number(message?.id);
      if (!Number.isSafeInteger(messageId) || messageId < 1) continue;
      for (const field of ["message", "admin_reply"]) {
        for (const path of getChatAttachmentReferences(message?.[field])) {
          const key = `${messageId}:${field}:${path}`;
          if (seen.has(key)) continue;
          seen.add(key);
          requestItems.push({ path, messageId, field });
        }
      }
    }
    return JSON.stringify(requestItems);
  }, [adminMessages, userInboxMessages]);

  useEffect(() => {
    let active = true;
    const requestItems = JSON.parse(chatAttachmentRequestKey);
    if (!requestItems.length) return undefined;

    let loading = false;
    async function loadPrivateAttachmentUrls() {
      if (loading || !active || document.visibilityState !== "visible") return;
      loading = true;
      try {
      const {
        data: { session },
        error: sessionError,
      } = await supabase.auth.getSession();
      if (!active || sessionError || !session?.access_token) return;

      for (let offset = 0; offset < requestItems.length; offset += 100) {
        const batch = requestItems.slice(offset, offset + 100);
        const response = await fetch("/api/support-attachments/access-urls", {
          method: "POST",
          credentials: "same-origin",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.access_token}`,
          },
          body: JSON.stringify({ attachments: batch }),
        });
        if (!response.ok) continue;
        const result = await response.json().catch(() => null);
        if (!active || !Array.isArray(result?.attachments)) continue;
        setChatAttachmentUrls((previous) => {
          const next = { ...previous };
          for (const attachment of result.attachments) {
            if (
              typeof attachment?.reference === "string" &&
              typeof attachment?.url === "string"
            ) {
              next[attachment.reference] = attachment.url;
            }
          }
          return next;
        });
      }
      } finally {
        loading = false;
      }
    }

    loadPrivateAttachmentUrls().catch((error) => {
      console.error("Support attachment links could not be refreshed:", error);
    });
    const refreshWhenVisible = () => {
      loadPrivateAttachmentUrls().catch((error) => {
        console.error("Support attachment links could not be refreshed:", error);
      });
    };
    const refreshTimer = window.setInterval(refreshWhenVisible, 45 * 60 * 1000);
    window.addEventListener("focus", refreshWhenVisible);
    document.addEventListener("visibilitychange", refreshWhenVisible);
    return () => {
      active = false;
      window.clearInterval(refreshTimer);
      window.removeEventListener("focus", refreshWhenVisible);
      document.removeEventListener("visibilitychange", refreshWhenVisible);
    };
  }, [chatAttachmentRequestKey, currentUser?.email]);

  function renderMsgContent(text, messageId, field = "message") {
    if (!text) return null;
    const quoted = extractQuoteSnippet(text);
    const body = quoted !== null ? stripQuoteMarker(text) : text;
    const clickable = quoted && quoted.id != null;
    const quoteBlock = quoted ? (
      <div
        key="quote"
        onClick={clickable ? () => jumpToChatMsg(quoted.id, quoted.side) : undefined}
        className={`mb-1.5 flex items-start gap-1.5 rounded-lg border-l-[3px] border-sky-400/70 bg-sky-400/10 pl-2.5 pr-2 py-1.5 text-xs text-white/75 italic truncate max-w-full ${clickable ? "cursor-pointer hover:bg-sky-400/20 transition-colors" : ""}`}
      >
        <span className="not-italic font-bold text-sky-300 shrink-0">↩</span>
        <span className="truncate">{quoted.text}</span>
      </div>
    ) : null;
    return [quoteBlock, ...renderMsgBody(body, messageId, field)];
  }

  function renderLinkedMessageText(text) {
    const nodes = [];
    let lastIndex = 0;
    for (const match of text.matchAll(/\b(?:https?:\/\/|www\.)[^\s<>"']+/gi)) {
      const urlText = match[0].replace(/[.,!?;:)\]}]+$/, "");
      if (!urlText) continue;
      const href = /^www\./i.test(urlText) ? `https://${urlText}` : urlText;
      try {
        const parsed = new URL(href);
        if (parsed.protocol !== "http:" && parsed.protocol !== "https:") continue;
      } catch {
        continue;
      }
      nodes.push(text.slice(lastIndex, match.index));
      nodes.push(
        <a key={match.index} href={href} target="_blank" rel="noopener noreferrer" className="break-all text-sky-300 underline underline-offset-2 hover:text-sky-200">
          {urlText}
        </a>
      );
      lastIndex = match.index + urlText.length;
    }
    nodes.push(text.slice(lastIndex));
    return nodes;
  }

  function renderMsgBody(text, messageId, field) {
    if (!text) return [];
    const parts = text.split(/(\[IMAGE:[^\]]+\]|\[FILE:[^\]]+\]|\[VIDEO:[^\]]+\])/g);
    return parts.map((part, i) => {
      const imgM = part.match(/^\[IMAGE:(.+)\]$/);
      if (imgM) {
        const attachmentUrl = chatAttachmentUrls[imgM[1]] || "";
        return (
          <img key={i} src={attachmentUrl || undefined} alt="" className="mt-1.5 max-w-[240px] max-h-[200px] rounded-xl object-cover cursor-pointer block" onClick={attachmentUrl ? () => setChatLightboxUrl(attachmentUrl) : undefined} />
        );
      }
      const videoM = part.match(/^\[VIDEO:(.+)\]$/);
      if (videoM) {
        const attachmentUrl = chatAttachmentUrls[videoM[1]] || "";
        return (
          <video key={i} src={attachmentUrl || undefined} controls playsInline className="mt-1.5 max-w-[280px] rounded-xl block" style={{maxHeight: "200px"}} />
        );
      }
      const fileM = part.match(/^\[FILE:(.+):([^\]]*)\]$/);
      if (fileM) {
        const [, url, encodedName] = fileM;
        let name = encodedName || "attachment";
        try {
          name = decodeURIComponent(name);
        } catch {
          // Older attachment messages may contain unescaped names.
        }
        const attachmentUrl = chatAttachmentUrls[url] || "";
        return (
          <a key={i} href={attachmentUrl || undefined} onClick={!attachmentUrl ? (event) => event.preventDefault() : undefined} target="_blank" rel="noopener noreferrer" aria-disabled={!attachmentUrl} className="mt-1.5 flex items-center gap-2 rounded-xl border border-white/20 bg-white/10 px-3 py-2 text-sm text-white hover:bg-white/15 max-w-[240px]">
            <svg className="w-5 h-5 shrink-0 text-red-400" viewBox="0 0 24 24" fill="currentColor"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6zm-1 1.5L18.5 9H13V3.5zM8.5 17h7v1h-7v-1zm0-3h7v1h-7v-1zm0-3H11v1H8.5v-1z"/></svg>
            <span className="truncate text-xs">{attachmentUrl ? (name || "document.pdf") : "Loading attachment…"}</span>
          </a>
        );
      }
      return part ? <span key={i} className="whitespace-pre-wrap break-words">{renderLinkedMessageText(part)}</span> : null;
    });
  }

  async function uploadAndSendAttachment(file, sendFn) {
    if (!currentUser?.email) {
      setUserInboxError("Sign in to send support messages.");
      return;
    }
    const fileExtension = file?.name?.match(/\.([^.]+)$/)?.[1]?.toLowerCase() || "";
    const supportedDocumentExtensions = new Set(["pdf", "txt", "csv", "doc", "docx", "xls", "xlsx", "ppt", "pptx", "rtf", "odt", "ods"]);
    const isImage = Boolean(file?.type?.startsWith('image/'));
    const isVideo = Boolean(file?.type?.startsWith('video/'));
    const isFile = file?.type === 'application/pdf' || supportedDocumentExtensions.has(fileExtension);
    if (!file || (!isImage && !isVideo && !isFile)) {
      if (file) alert('Choose an image, video, or supported document file.');
      return;
    }
    if (file.size > 100 * 1024 * 1024) { alert('Attachment must be under 100 MB'); return; }
    setChatAttachmentUploading(true);
    try {
      const {
        data: { session },
        error: sessionError,
      } = await supabase.auth.getSession();
      if (sessionError) throw new Error("Could not verify your support session.");
      const uploadHeaders = { "Content-Type": "application/json" };
      if (session?.access_token) {
        uploadHeaders.Authorization = `Bearer ${session.access_token}`;
      }
      const uploadUrlResponse = await fetch(
        "/api/support-attachments/upload-url",
        {
          method: "POST",
          credentials: "same-origin",
          headers: uploadHeaders,
          body: JSON.stringify({
            fileName: file.name,
            contentType: file.type || "",
            size: file.size,
          }),
        },
      );
      const uploadDetails = await uploadUrlResponse.json().catch(() => null);
      if (!uploadUrlResponse.ok || !uploadDetails?.uploadUrl || !uploadDetails?.path) {
        throw new Error(uploadDetails?.error || "Could not prepare the attachment upload.");
      }

      const storageResponse = await fetch(uploadDetails.uploadUrl, {
        method: "PUT",
        headers: {
          "Content-Type": uploadDetails.contentType,
          "cache-control": "max-age=3600",
          "x-upsert": "false",
        },
        body: file,
      });
      if (!storageResponse.ok) {
        throw new Error("The attachment could not be uploaded. Please try again.");
      }

      const previewUrl = URL.createObjectURL(file);
      chatAttachmentObjectUrlsRef.current.add(previewUrl);
      setChatAttachmentUrls((previous) => ({
        ...previous,
        [uploadDetails.path]: previewUrl,
      }));
      await sendFn(uploadDetails.path, file.name, isFile, isVideo);
    } catch (err) {
      alert('Upload failed: ' + err.message);
    } finally {
      setChatAttachmentUploading(false);
    }
  }

  async function sendAttachmentAsUserMessage(url, fileName, isFile, isVideo) {
    if (!currentUser?.email) {
      setUserInboxError("Sign in to send support messages.");
      return;
    }
    const name = contactForm.name.trim() || (currentUser?.email || "Anonymous");
    const email = (currentUser?.email || contactForm.email.trim() || "").toLowerCase();
    const tag = isVideo ? `[VIDEO:${url}]` : isFile ? `[FILE:${url}:${encodeURIComponent(fileName || 'attachment')}]` : `[IMAGE:${url}]`;
    const quotePrefix = replyPreview ? `[QUOTE:${encodeURIComponent(JSON.stringify(replyPreview))}]` : "";
    const message = quotePrefix + tag;
    const { error } = await supabase.from("contact_messages").insert({ name, email, message });
    setReplyPreview(null);
    if (error) { alert("Send failed: " + error.message); return; }
    const optimistic = { id: "opt-" + Date.now(), name, email, message, created_at: new Date().toISOString(), admin_reply: null };
    setUserInboxMessages((prev) => [...prev, optimistic]);
    loadUserInbox();
  }

  function showAdminDeliveryMessage(text, duration = 10000) {
    setAdminMessage(text);
    clearTimeout(window.__tbvAdminMessageTimeout);
    window.__tbvAdminMessageTimeout = setTimeout(() => setAdminMessage(""), duration);
  }

  async function sendAttachmentAsAdminMessage(url, toEmail, lastUnanswered, fileName, isFile, isVideo) {
    if (adminSendingRef.current) { showAdminDeliveryMessage("Wait for the current support message to finish."); return; }
    adminSendingRef.current = true;
    const fileTag = isVideo ? `[VIDEO:${url}]` : isFile ? `[FILE:${url}:${encodeURIComponent(fileName || 'attachment')}]` : `[IMAGE:${url}]`;
    const quotePrefix = adminReplyPreview ? `[QUOTE:${encodeURIComponent(JSON.stringify(adminReplyPreview))}]` : "";
    const tag = quotePrefix + fileTag;
    try {
      if (lastUnanswered) {
        const { data, error } = await supabase.from("contact_messages").update({ admin_reply: tag, replied_at: new Date().toISOString(), user_read_at: null }).eq("id", lastUnanswered.id).select("id").single();
        if (error) throw new Error(error.message);
      } else {
        const { data, error } = await supabase.from("contact_messages").insert({ name: "Support", email: toEmail.trim().toLowerCase(), message: "[Admin initiated message]", admin_reply: tag, replied_at: new Date().toISOString(), user_read_at: null }).select("id").single();
        if (error) throw new Error(error.message);
      }
      setAdminReplyPreview(null);
      loadAdminMessages();
      showAdminDeliveryMessage("Message saved in the site's Support inbox.");
    } catch (err) {
      alert('Send failed: ' + err.message);
    } finally {
      adminSendingRef.current = false;
    }
  }

  function setupTypingChannel(email) {
    if (typingChannelRef.current) {
      supabase.removeChannel(typingChannelRef.current);
      typingChannelRef.current = null;
    }
    if (!email) return;
    const amAdmin = ADMIN_EMAILS.includes(normalizeEmail(email) === normalizeEmail(currentUser?.email) ? '' : currentUser?.email || '');
    const ch = supabase.channel(`chat-typing:${email.toLowerCase()}`);
    ch.on('broadcast', { event: 'typing' }, ({ payload }) => {
      clearTimeout(typingStopTimerRef.current);
      if (ADMIN_EMAILS.includes(normalizeEmail(currentUser?.email)) && payload.role === 'user') {
        setUserIsTyping(true);
        typingStopTimerRef.current = setTimeout(() => setUserIsTyping(false), 3500);
      } else if (!ADMIN_EMAILS.includes(normalizeEmail(currentUser?.email)) && payload.role === 'admin') {
        setAdminIsTyping(true);
        typingStopTimerRef.current = setTimeout(() => setAdminIsTyping(false), 3500);
      }
    }).subscribe();
    typingChannelRef.current = ch;
  }

  function broadcastTyping(role) {
    if (!typingChannelRef.current) return;
    typingChannelRef.current.send({ type: 'broadcast', event: 'typing', payload: { role } });
  }

  async function sendContactMessage(messageDraft = contactForm.message) {
    if (!currentUser?.email) {
      setUserInboxError("Sign in to send support messages.");
      return false;
    }
    const messageText = String(messageDraft ?? "").slice(0, 1000);
    if (!messageText.trim()) return false;
    setContactSending(true);
    const name = contactForm.name.trim() || (currentUser?.email || "Anonymous");
    // Logged-in account email always wins — a stale/typed value in contactForm.email
    // (e.g. left over from a guest session) must never override the real account.
    const email = (currentUser?.email || contactForm.email.trim() || "").toLowerCase();
    const quotePrefix = replyPreview ? `[QUOTE:${encodeURIComponent(JSON.stringify(replyPreview))}]` : "";
    const message = quotePrefix + messageText.trim();
    const { error } = await supabase.from("contact_messages").insert({ name, email, message });
    setContactSending(false);
    if (error) {
      alert("Send failed: " + error.message);
      return false;
    }
    // Clear input and add optimistic message immediately
    setContactForm((f) => ({ ...f, message: "" }));
    setReplyPreview(null);
    const optimistic = { id: "opt-" + Date.now(), name, email, message, created_at: new Date().toISOString(), admin_reply: null };
    setUserInboxMessages((prev) => [...prev, optimistic]);
    // Then sync from server to get the real id
    loadUserInbox();
    return true;
  }

  async function loadAdminMessages() {
    setAdminMessagesLoading(true);
    const { data } = await supabase.from("contact_messages").select("*").order("created_at", { ascending: false });
    setAdminMessages(data || []);
    setAdminMessagesLoading(false);
    loadReactions();
  }

  useEffect(() => {
    if (!isAdminUser()) return;
    const id = window.setInterval(loadAdminMessages, 30000);
    return () => window.clearInterval(id);
  }, [currentUser?.email]);

  const [adminInboxLastSeen, setAdminInboxLastSeen] = useState(
    () => localStorage.getItem("tbv-admin-inbox-seen") || ""
  );

  useEffect(() => {
    if (page === "admin" && isAdminUser()) {
      const now = new Date().toISOString();
      localStorage.setItem("tbv-admin-inbox-seen", now);
      setAdminInboxLastSeen(now);
      // Preload jsPDF so invoice download is instant on first click
      if (!window.jspdf) {
        const s = document.createElement("script");
        s.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
        document.head.appendChild(s);
      }
    }
  }, [page]);

  useEffect(() => {
    if (page !== "account") {
      orderLoadInitiatedRef.current = false;
      return;
    }
    if (!currentUser?.email) return;
    if (ADMIN_EMAILS.includes(normalizeEmail(currentUser.email))) return;
    if (orderLoadInitiatedRef.current) return;
    orderLoadInitiatedRef.current = true;
    console.log("[TBV] auto-trigger: calling refresh for", currentUser?.email);
    refreshUserOrdersFromSupabase();
  }, [page, currentUser?.email]);

  const adminUnreadCount = useMemo(() => {
    if (!adminMessages.length) return 0;
    const threadMap = {};
    adminMessages.forEach((m) => {
      const k = m.email || "?";
      if (!threadMap[k]) threadMap[k] = [];
      threadMap[k].push(m);
    });
    return Object.values(threadMap).filter((msgs) => {
      const email = msgs[0]?.email || "?";
      const lastRead = readThreadTimestamps.get(email);
      const clientMsgs = msgs.filter(m => m.message !== "[Admin initiated message]" && !m.admin_reply);
      if (clientMsgs.length === 0) return false;
      const latestClientTs = Math.max(...clientMsgs.map(m => new Date(m.created_at).getTime()));
      if (lastRead && latestClientTs <= lastRead) return false;
      if (!adminInboxLastSeen) return false;
      return latestClientTs > new Date(adminInboxLastSeen).getTime();
    }).length;
  }, [adminMessages, adminInboxLastSeen, readThreadTimestamps]);

  async function deleteAdminReply(id) {
    try {
      const { error } = await supabase
        .from("contact_messages")
        .update({ admin_reply: null, replied_at: null })
        .eq("id", id);
      if (error) throw error;
      setAdminMessages((prev) => prev.map((m) => m.id === id ? { ...m, admin_reply: null, replied_at: null } : m));
    } catch (err) {
      setAdminMessage(`Delete reply failed: ${err.message}`);
      clearTimeout(window.__tbvAdminMessageTimeout);
      window.__tbvAdminMessageTimeout = setTimeout(() => setAdminMessage(""), 5000);
    }
  }

  async function loadReactions() {
    try {
      const resp = await fetch("/api/reactions");
      if (!resp.ok) return;
      const data = await resp.json();
      const flat = {};
      for (const [msgId, sides] of Object.entries(data)) {
        flat[`in_${msgId}`] = sides.msg || {};
        flat[`out_${msgId}`] = sides.reply || {};
        flat[`usr_sent_${msgId}`] = sides.msg || {};
        flat[`usr_rcvd_${msgId}`] = sides.reply || {};
      }
      setMsgReactions(flat);
    } catch {}
  }

  async function toggleReaction(rKey, emoji) {
    let msgId, side;
    if (rKey.startsWith("in_")) { msgId = rKey.slice(3); side = "msg"; }
    else if (rKey.startsWith("out_")) { msgId = rKey.slice(4); side = "reply"; }
    else if (rKey.startsWith("usr_sent_")) { msgId = rKey.slice(9); side = "msg"; }
    else if (rKey.startsWith("usr_rcvd_")) { msgId = rKey.slice(9); side = "reply"; }
    else return;

    setMsgReactions(prev => {
      const curMsg = { ...(prev[`in_${msgId}`] || {}) };
      const curReply = { ...(prev[`out_${msgId}`] || {}) };
      if (side === "msg") curMsg[emoji] = !curMsg[emoji];
      else curReply[emoji] = !curReply[emoji];

      fetch(`/api/reactions/${msgId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ reactions: { msg: curMsg, reply: curReply } }),
      }).catch(() => {});

      return {
        ...prev,
        [`in_${msgId}`]: curMsg,
        [`out_${msgId}`]: curReply,
        [`usr_sent_${msgId}`]: curMsg,
        [`usr_rcvd_${msgId}`]: curReply,
      };
    });
  }

  async function sendAdminReply(id, { isEdit = false, messageText } = {}) {
    const replyDraft = messageText ?? adminReplyInputRef.current?.value ?? adminReplyText;
    if (!replyDraft.trim() || adminSendingRef.current) return;
    adminSendingRef.current = true;
    try {
      const quotePrefix = (!isEdit && adminReplyPreview) ? `[QUOTE:${encodeURIComponent(JSON.stringify(adminReplyPreview))}]` : "";
      const reply = quotePrefix + replyDraft.trim();
      const change = { admin_reply: reply, replied_at: new Date().toISOString(), ...(!isEdit && { user_read_at: null }) };
      const { data, error: patchErr } = await supabase
        .from("contact_messages")
        .update(change)
        .eq("id", id)
        .select("id")
        .single();
      if (patchErr) throw new Error(patchErr.message);
      setAdminReplyingId(null);
      setAdminReplyText("");
      setAdminReplyPreview(null);
      loadAdminMessages();
      showAdminDeliveryMessage(isEdit ? "Reply updated in the site's Support inbox." : "Reply saved in the site's Support inbox.");
    } catch (err) {
      setAdminMessage(`Reply failed: ${err.message}`);
      clearTimeout(window.__tbvAdminMessageTimeout);
      window.__tbvAdminMessageTimeout = setTimeout(() => setAdminMessage(""), 8000);
    } finally {
      adminSendingRef.current = false;
    }
  }

  async function sendAdminFollowUp(toEmail, messageText) {
    const replyDraft = messageText ?? adminReplyInputRef.current?.value ?? adminReplyText;
    if (!replyDraft.trim() || adminSendingRef.current) return;
    adminSendingRef.current = true;
    try {
      const quotePrefix = adminReplyPreview ? `[QUOTE:${encodeURIComponent(JSON.stringify(adminReplyPreview))}]` : "";
      const reply = quotePrefix + replyDraft.trim();
      const { data, error } = await supabase.from("contact_messages").insert({
        name: "Support",
        email: toEmail.trim().toLowerCase(),
        message: "[Admin initiated message]",
        admin_reply: reply,
        replied_at: new Date().toISOString(),
        user_read_at: null,
      }).select("id").single();
      if (error) throw new Error(error.message);
      setAdminReplyText("");
      setAdminReplyPreview(null);
      loadAdminMessages();
      showAdminDeliveryMessage("Message saved in the site's Support inbox.");
    } catch (err) {
      setAdminMessage(`Send failed: ${err.message}`);
      clearTimeout(window.__tbvAdminMessageTimeout);
      window.__tbvAdminMessageTimeout = setTimeout(() => setAdminMessage(""), 8000);
    } finally {
      adminSendingRef.current = false;
    }
  }

  async function deleteMessage(id, { fromAdmin = false } = {}) {
    try {
      const { error } = await supabase.from("contact_messages").delete().eq("id", id);
      if (error) throw error;
      if (fromAdmin) {
        setAdminMessages((prev) => prev.filter((m) => m.id !== id));
      } else {
        setUserInboxMessages((prev) => prev.filter((m) => m.id !== id));
        if (expandedMsgId === id) setExpandedMsgId(null);
      }
    } catch (err) {
      setAdminMessage(`Delete failed: ${err.message}`);
      clearTimeout(window.__tbvAdminMessageTimeout);
      window.__tbvAdminMessageTimeout = setTimeout(() => setAdminMessage(""), 5000);
    }
  }

  async function editUserMessage(id, messageText) {
    const currentText = messageText ?? editingMessageInputRef.current?.value ?? editingMsgText;
    const trimmed = currentText.trim();
    if (!trimmed) return;
    try {
      const { error } = await supabase.from("contact_messages").update({ message: trimmed }).eq("id", id);
      if (error) throw error;
      setUserInboxMessages((prev) => prev.map((m) => m.id === id ? { ...m, message: trimmed } : m));
      setEditingMsgId(null);
      setEditingMsgText("");
    } catch (err) {
      console.error("Edit message failed:", err.message);
    }
  }

  async function checkUnreadReply() {
    if (!currentUser?.email) return;
    const { data } = await supabase
      .from("contact_messages")
      .select("id")
      .eq("email", currentUser.email.toLowerCase())
      .not("admin_reply", "is", null)
      .is("user_read_at", null)
      .limit(1);
    setHasUnreadReply((data || []).length > 0);
  }

  async function markRepliesRead(messages, email) {
    const unreadIds = messages.filter((m) => m.admin_reply && !m.user_read_at).map((m) => m.id);
    if (!unreadIds.length) return;
    const { data, error } = await supabase
      .from("contact_messages")
      .update({ user_read_at: new Date().toISOString() })
      .eq("email", email)
      .in("id", unreadIds)
      .is("user_read_at", null)
      .select("id,user_read_at");
    if (error) {
      console.error("Support read status update failed:", error);
      return;
    }
    if (!data?.length || userInboxEmailRef.current !== email) return;
    const markedIds = new Set(data.map((m) => m.id));
    setUserInboxMessages((prev) => prev.map((m) =>
      markedIds.has(m.id) ? { ...m, user_read_at: data.find((row) => row.id === m.id).user_read_at } : m
    ));
    setHasUnreadReply(messages.some((m) => m.admin_reply && !m.user_read_at && !markedIds.has(m.id)));
  }

  async function sendAdminCompose() {
    if (!adminComposeTo.trim() || !adminComposeText.trim() || adminSendingRef.current) return;
    const recipient = normalizeEmail(adminComposeTo);
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipient)) {
      showAdminDeliveryMessage("Enter a valid account email for this site message.");
      return;
    }
    adminSendingRef.current = true;
    setAdminComposeSending(true);
    try {
      const reply = adminComposeText.trim();
      const { data, error } = await supabase.from("contact_messages").insert({
        name: "Support",
        email: recipient,
        message: "[Admin initiated message]",
        admin_reply: reply,
        replied_at: new Date().toISOString(),
        user_read_at: null,
      }).select("id").single();
      if (error) throw new Error(error.message);
      setAdminComposeTo("");
      setAdminComposeText("");
      setAdminComposeOpen(false);
      loadAdminMessages();
      checkUnreadReply();
      showAdminDeliveryMessage(`Message saved for ${recipient}. It appears in the site's Support chat under that account.`);
    } catch (error) {
      showAdminDeliveryMessage(`Send failed: ${error.message}`);
    } finally {
      setAdminComposeSending(false);
      adminSendingRef.current = false;
    }
  }

  async function loadUserInbox(silent = false, markVisibleRead = false) {
    const email = currentUser?.email?.trim().toLowerCase() || "";
    if (!email) {
      userInboxRequestIdRef.current += 1;
      userInboxEmailRef.current = "";
      setUserInboxMessages([]);
      setHasUnreadReply(false);
      setUserInboxError("Sign in to view your support messages.");
      setUserInboxLoading(false);
      return;
    }
    if (userInboxEmailRef.current !== email) {
      userInboxEmailRef.current = email;
      setUserInboxMessages([]);
      setUserInboxError("");
      setHasUnreadReply(false);
    }
    const requestId = ++userInboxRequestIdRef.current;
    if (!silent) setUserInboxLoading(true);
    const { data, error } = await supabase
      .from("contact_messages")
      .select("*")
      .eq("email", email)
      .order("created_at", { ascending: true });
    if (requestId !== userInboxRequestIdRef.current) return;
    if (error) {
      console.error("Support inbox load failed:", error);
      setUserInboxError("Messages could not be loaded. Please try again.");
      setUserInboxLoading(false);
      return;
    }
    setUserInboxError("");
    setUserInboxMessages(data || []);
    setHasUnreadReply((data || []).some(m => m.admin_reply && !m.user_read_at));
    setUserInboxLoading(false);
    if (markVisibleRead && supportConversationOpenRef.current && currentUser?.email?.toLowerCase() === email) {
      markRepliesRead(data || [], email).catch((readError) => console.error("Support read status update failed:", readError));
    }
    loadReactions();
  }

  function getAffiliateCommissionBaseAmount(order) {
    const subtotal = Number(order?.subtotal || 0);
    if (subtotal > 0) return subtotal * 0.1;
    return Number(order?.affiliateCommission || 0);
  }

  function isCommissionEligibleOrder(order) {
    const status = String(order?.status || "").toLowerCase();
    return status === "paid" || status === "done";
  }

  function isOrderDone(order) {
    if (!isCommissionEligibleOrder(order)) return false;
    const status = String(order?.status || "").toLowerCase();
    return status === "done" || isAffiliateCommissionAvailable(order);
  }

  function getAffiliateCommissionAdjustment(order) {
    return Number(
      order?.affiliateCommissionAdjustment ||
        order?.affiliateCommissionDeduction ||
        order?.refundCommissionDeduction ||
        0
    );
  }

  function getAffiliateCommissionNetAmount(order) {
    return Math.max(0, getAffiliateCommissionBaseAmount(order) - getAffiliateCommissionAdjustment(order));
  }

  function getAffiliateReleaseDays(order) {
    // US warehouse: order.fromWarehouse, or shippingType contains "us-warehouse",
    // or ALL items have fromWarehouse === "us"
    const itemsAllUS = Array.isArray(order?.items) && order.items.length > 0 && order.items.every(i => i.fromWarehouse === "us");
    const isUS = order?.fromWarehouse === "us"
      || String(order?.shippingType || "").toLowerCase().includes("us-warehouse")
      || itemsAllUS;
    if (isUS) return 6;
    const isExpress = String(order?.shippingType || "").toLowerCase().includes("express");
    if (isExpress) return 10;
    return 15;
  }

  function getAffiliateAvailableAt(order) {
    const baseDate = order?.paidAt || order?.createdAt;
    if (!baseDate) return null;
    const date = new Date(baseDate);
    if (Number.isNaN(date.getTime())) return null;
    date.setDate(date.getDate() + getAffiliateReleaseDays(order));
    return date;
  }

  function isAffiliateCommissionAvailable(order) {
    const availableAt = getAffiliateAvailableAt(order);
    return availableAt ? Date.now() >= availableAt.getTime() : false;
  }

  async function loadStoreCredit(email) {
    if (!email) return;
    try {
      const { data } = await supabase
        .from("user_credits")
        .select("amount")
        .eq("email", email.toLowerCase().trim())
        .maybeSingle();
      setStoreCredit(data ? Number(data.amount ?? 0) : 0);
    } catch { /* ignore */ }
  }

  async function adminAddCredit(mode) {
    if (adminCreditAdjustmentBusyRef.current) return;
    adminCreditAdjustmentBusyRef.current = true;
    setAdminCreditLoading(true);
    setAdminCreditMessage("");
    try {
      const result = await adjustStoreCredit({ supabase, storage: window.sessionStorage,
        email: adminCreditEmail, mode, amount: adminCreditAmount, note: adminCreditNote });
      setAdminCreditMessage(`✓ ${result.email} — adjustment confirmed; balance after adjustment: $${result.balance.toFixed(2)}`);
      // An idempotent replay may predate a later checkout. Refresh the current
      // balance separately instead of presenting its old receipt as live credit.
      setAdminCreditLookup(null);
      try {
        const { data, error } = await supabase.from("user_credits").select("amount, updated_at, note").eq("email", result.email).maybeSingle();
        const balance = Number(data?.amount);
        if (!error && data && Number.isFinite(balance) && balance >= 0) {
          setAdminCreditLookup({ email: result.email, amount: balance, updated_at: data.updated_at, note: data.note });
          if (currentUser?.email?.trim().toLowerCase() === result.email) setStoreCredit(balance);
        }
      } catch { /* The adjustment is confirmed; the current-balance refresh can be retried. */ }
    } catch (error) {
      setAdminCreditMessage(error?.message || "Store credit could not be confirmed. Retry the same adjustment.");
    } finally {
      adminCreditAdjustmentBusyRef.current = false;
      setAdminCreditLoading(false);
    }
  }

  async function adminLookupCredit() {
    const email = adminCreditEmail.trim().toLowerCase();
    if (!email) return;
    try {
      const { data } = await supabase.from("user_credits").select("amount, updated_at, note").eq("email", email).maybeSingle();
      setAdminCreditLookup(data ? { email, amount: Number(data.amount), updated_at: data.updated_at, note: data.note } : { email, amount: 0 });
    } catch { setAdminCreditLookup({ email, amount: 0 }); }
  }

  async function fetchUserPromos(email, currentAppliedPromo) {
    if (!email) return;
    try {
      const { data, error } = await supabase
        .from("user_promos")
        .select("*")
        .eq("email", String(email).trim().toLowerCase());
      if (!error && Array.isArray(data)) {
        const activePromos = data.filter((p) => !p.used);
        setUserPromos(activePromos);
        if (activePromos.length > 0 && !currentAppliedPromo) {
          const first = activePromos[0];
          setAppliedPromo({
            code: first.code,
            rate: first.rate,
            label: `${+(first.rate * 100).toFixed(2)}% discount`,
            type: "user_promo",
            id: first.id,
            issuedAt: first.created_at || "",
          });
        }
      }
    } catch (e) {
      console.error("Failed to fetch user promos:", e);
    }
  }

  async function issueUserPromo() {
    const email = issuePromoEmail.trim().toLowerCase();
    const code = issuePromoCode.trim().toUpperCase();
    const rate = parseFloat(issuePromoRate);
    if (!email || !code || !rate || rate <= 0 || rate > 100) {
      setIssuePromoMessage("Fill all fields correctly. Rate: 1–100.");
      return;
    }
    try {
      const rateDecimal = rate > 1 ? rate / 100 : rate;
      const { error } = await supabase.from("user_promos").insert({
        email,
        code,
        rate: rateDecimal,
        used: false,
      });
      if (error) {
        setIssuePromoMessage(`Error: ${error.message}`);
      } else {
        setIssuePromoMessage(`✓ Promo ${code} (${rate}%) issued to ${email}`);
        setIssuePromoEmail("");
        setIssuePromoCode("");
        setIssuePromoRate("");
        fetch("/api/send-promo-code-email", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email, code, rate: rateDecimal }),
        }).catch((e) => console.error("Failed to send promo code email:", e));
      }
    } catch (e) {
      setIssuePromoMessage(`Error: ${String(e)}`);
    }
    window.setTimeout(() => setIssuePromoMessage(""), 6000);
  }

  async function loadPublicPromos() {
    try {
      const { data, error } = await supabase
        .from("user_promos")
        .select("id,code,rate,created_at")
        .eq("email", "__PUBLIC__")
        .order("created_at", { ascending: false });
      if (!error && Array.isArray(data)) setPublicPromos(data);
    } catch (e) { console.error("loadPublicPromos", e); }
  }

  async function createPublicPromo() {
    const code = publicPromoCode.trim().toUpperCase();
    const rate = parseFloat(publicPromoRate);
    if (!code || !rate || rate <= 0 || rate > 100) {
      setPublicPromoMessage("Введи код и скидку (1–100%).");
      window.setTimeout(() => setPublicPromoMessage(""), 4000);
      return;
    }
    const rateDecimal = rate / 100;
    try {
      const { error } = await supabase.from("user_promos").insert({ email: "__PUBLIC__", code, rate: rateDecimal, used: false });
      if (error) { setPublicPromoMessage(`Error: ${error.message}`); }
      else {
        setPublicPromoMessage(`✓ Промокод ${code} (${rate}%) опубликован`);
        setPublicPromoCode(""); setPublicPromoRate("");
        loadPublicPromos();
      }
    } catch (e) { setPublicPromoMessage(`Error: ${String(e)}`); }
    window.setTimeout(() => setPublicPromoMessage(""), 5000);
  }

  async function deletePublicPromo(id, code) {
    if (!window.confirm(`Удалить промокод ${code}?`)) return;
    await supabase.from("user_promos").delete().eq("id", id);
    setPublicPromos(prev => prev.filter(p => p.id !== id));
  }

  async function sendTrackingEmail({ email, orderId, trackingNumber, firstName }) {
    const orderKey = String(orderId || "");
    setSendingTrackingEmailOrders((previous) => new Set(previous).add(orderKey));
    try {
      const { data: { session }, error: sessionError } = await supabase.auth.getSession();
      if (sessionError) throw new Error(sessionError.message);
      if (!session?.access_token) throw new Error("Admin sign-in required");

      const res = await fetch("/api/supabase/send-tracking-email", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${session.access_token}`,
        },
        body: JSON.stringify({ email, orderId, trackingNumber, firstName }),
      });
      const data = await res.json().catch(() => ({}));
      if (res.ok) {
        setAdminMessage(`Tracking email sent to ${email}`);
        window.clearTimeout(window.__tbvAdminMessageTimeout);
        window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 4000);
      } else {
        setAdminMessage(`Tracking email failed: ${data?.error || res.status}`);
        window.clearTimeout(window.__tbvAdminMessageTimeout);
        window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 6000);
      }
    } catch (e) {
      console.error("[sendTrackingEmail] error:", e);
      setAdminMessage(`Tracking email error: ${e?.message}`);
      window.clearTimeout(window.__tbvAdminMessageTimeout);
      window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 6000);
    } finally {
      setSendingTrackingEmailOrders((previous) => {
        const next = new Set(previous);
        next.delete(orderKey);
        return next;
      });
    }
  }

  async function generateInvoicePDF(order) {
    if (!window.jspdf) {
      await new Promise((resolve, reject) => {
        const s = document.createElement("script");
        s.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
        s.onload = resolve; s.onerror = reject;
        document.head.appendChild(s);
      });
    }
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: "mm", format: "a4" });
    const W = 210; const margin = 18;
    let y = 0;

    // ── Header bar ──────────────────────────────────────────────────────────
    doc.setFillColor(18, 18, 18);
    doc.rect(0, 0, W, 32, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(18);
    doc.setFont("helvetica", "bold");
    doc.text("10BottleValueCo", margin, 14);
    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(180, 180, 180);
    doc.text("10bottlevalue.co  ·  support@10bottlevalue.co", margin, 22);
    doc.setFontSize(8);
    doc.text("Research peptides — 10-vial kits", margin, 28);

    // Status badge
    const statusText = String(order.status || "paid").toUpperCase();
    doc.setFillColor(34, 197, 94);
    doc.roundedRect(W - margin - 24, 10, 24, 10, 2, 2, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(7);
    doc.setFont("helvetica", "bold");
    doc.text(statusText, W - margin - 12, 16.5, { align: "center" });

    y = 42;

    // ── Title ------------------------------------------------------------────
    doc.setTextColor(20, 20, 20);
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text("PAYMENT CONFIRMATION", margin, y);
    y += 6;
    doc.setDrawColor(230, 230, 230);
    doc.setLineWidth(0.3);
    doc.line(margin, y, W - margin, y);
    y += 7;

    // ── Order meta ───────────────────────────────────────────────────────────
    const paidDate = order.paidAt || order.createdAt || new Date().toISOString();
    const fmtDate = new Date(paidDate).toLocaleString("en-GB", { day: "2-digit", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit" });

    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(80, 80, 80);
    doc.text("ORDER NUMBER", margin, y);
    doc.text("DATE", W / 2 + 5, y);
    y += 5;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.setTextColor(20, 20, 20);
    doc.text(String(order.invoiceId || order.id || "—"), margin, y);
    doc.setFontSize(9);
    doc.setFont("helvetica", "normal");
    doc.text(fmtDate, W / 2 + 5, y);

    if (order.paymentProvider && order.paymentProvider !== "pending") {
      y += 5;
      doc.setFontSize(8);
      doc.setTextColor(100, 100, 100);
      doc.text(`Payment method: ${publicPaymentMethod(order.paymentProvider)}${order.paymentId ? "  ·  Ref: " + order.paymentId.slice(0, 28) : ""}`, margin, y);
    }
    y += 4;

    // ── Separator ------------------------------------------------------------
    doc.setDrawColor(230, 230, 230);
    doc.line(margin, y, W - margin, y);
    y += 7;

    // ── Customer info ────────────────────────────────────────────────────────
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(80, 80, 80);
    doc.text("BILL / SHIP TO", margin, y);
    doc.text("CONTACT", W / 2 + 5, y);
    y += 5;
    doc.setFont("helvetica", "normal");
    doc.setTextColor(20, 20, 20);
    doc.setFontSize(9.5);

    const name = [order.firstName, order.lastName].filter(Boolean).join(" ") || "—";
    doc.setFont("helvetica", "bold");
    doc.text(name, margin, y);
    doc.setFont("helvetica", "normal");
    doc.text(order.email || "—", W / 2 + 5, y);
    y += 5;
    if (order.address) { doc.text(order.address, margin, y); y += 5; }
    if (order.city || order.postalCode) { doc.text([order.city, order.postalCode].filter(Boolean).join(", "), margin, y); y += 5; }
    if (order.country) { doc.text(order.country, margin, y); }
    if (order.phone) { doc.text(`Tel: ${order.phone}`, W / 2 + 5, y); }
    y += 8;

    // ── Items table ──────────────────────────────────────────────────────────
    doc.setFillColor(30, 30, 30);
    doc.rect(margin, y, W - margin * 2, 7, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(8);
    doc.setFont("helvetica", "bold");
    doc.text("ITEM", margin + 3, y + 4.7);
    doc.text("QTY", W - margin - 42, y + 4.7, { align: "right" });
    doc.text("UNIT PRICE", W - margin - 22, y + 4.7, { align: "right" });
    doc.text("TOTAL", W - margin - 2, y + 4.7, { align: "right" });
    y += 7;

    doc.setTextColor(20, 20, 20);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    const items = Array.isArray(order.items) ? order.items : [];
    items.forEach((item, i) => {
      if (i % 2 === 0) { doc.setFillColor(248, 248, 248); doc.rect(margin, y, W - margin * 2, 6.5, "F"); }
      const qty = item.quantity ?? item.qty ?? 1;
      doc.text(`${publicProductName(item.name)} ${item.dose || ""}`.trim(), margin + 3, y + 4.5);
      doc.text(String(qty), W - margin - 42, y + 4.5, { align: "right" });
      doc.text(`$${Number(item.price || 0).toFixed(2)}`, W - margin - 22, y + 4.5, { align: "right" });
      doc.text(`$${(Number(item.price || 0) * qty).toFixed(2)}`, W - margin - 2, y + 4.5, { align: "right" });
      y += 6.5;
    });
    doc.setDrawColor(220, 220, 220);
    doc.line(margin, y, W - margin, y);
    y += 6;

    // ── Price breakdown ───────────────────────────────────────────────────────
    const col1 = W - margin - 60; const col2 = W - margin - 2;
    const row = (label, value, bold = false, color = null) => {
      doc.setFontSize(9);
      doc.setFont("helvetica", bold ? "bold" : "normal");
      if (color) doc.setTextColor(...color); else doc.setTextColor(60, 60, 60);
      doc.text(label, col1, y, { align: "right" });
      if (color) doc.setTextColor(...color); else doc.setTextColor(20, 20, 20);
      doc.text(value, col2, y, { align: "right" });
      y += 5.5;
    };
    row("Subtotal:", `$${Number(order.subtotal || 0).toFixed(2)}`);
    row("Shipping:", Number(order.shipping) === 0 ? "FREE" : `+$${Number(order.shipping || 0).toFixed(2)}`);
    if (Number(order.automaticDiscount) > 0) row("Bulk discount:", `-$${Number(order.automaticDiscount).toFixed(2)}`, false, [34, 197, 94]);
    if (Number(order.promoDiscount) > 0) row(`Promo (${order.promoCode || ""}):`, `-$${Number(order.promoDiscount).toFixed(2)}`, false, [34, 197, 94]);
    if (Number(order.affiliateDiscount) > 0) row("Affiliate discount:", `-$${Number(order.affiliateDiscount).toFixed(2)}`, false, [34, 197, 94]);
    if (Number(order.storeCreditUsed) > 0) row("Store credits:", `-$${Number(order.storeCreditUsed).toFixed(2)}`, false, [6, 182, 212]);
    if (Number(order.paypalFee) > 0) row("Processing fee:", `+$${Number(order.paypalFee).toFixed(2)}`);

    // Total box
    doc.setFillColor(20, 20, 20);
    doc.rect(W - margin - 64, y - 1, 64, 9, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.text("TOTAL PAID:", W - margin - 36, y + 5.5, { align: "right" });
    doc.text(`$${Number(order.total || 0).toFixed(2)}`, W - margin - 2, y + 5.5, { align: "right" });
    y += 16;

    // ── Footer ------------------------------------------------------------────
    doc.setDrawColor(220, 220, 220);
    doc.line(margin, y, W - margin, y);
    y += 5;
    doc.setFontSize(7.5);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(130, 130, 130);
    doc.text("This document confirms payment received by 10BottleValueCo.", margin, y);
    y += 4.5;
    doc.text("All products are for laboratory research use only. Not for human or animal use.", margin, y);
    y += 4.5;
    doc.text(`Shipping method: ${order.shippingType || "standard"}`, margin, y);
    if (order.trackingNumber) { doc.text(`Tracking: ${order.trackingNumber}`, margin + 75, y); }

    doc.save(`Invoice_${order.id || "order"}.pdf`);
  }

  function updateOrderAdminField(orderId, field, value) {
    const orders = getStoredOrders();
    let supabasePayload = null;
    let trackingEmailData = null;
    let adminNoteValue = null;
    const nextOrders = orders.map((order) => {
      if (order.id !== orderId) return order;
      if (field === "status") {
        const nextStatus = String(value || "pending").toLowerCase();
        const nextPaidAt = ["paid", "done"].includes(nextStatus)
          ? order.paidAt || new Date().toISOString()
          : order.paidAt || "";
        supabasePayload = { status: nextStatus };
        const isRefundedOrCancelled = nextStatus === "refunded" || nextStatus === "cancelled";
        return {
          ...order,
          status: nextStatus,
          paidAt: nextPaidAt,
          // Zero out affiliate commission locally so UI reflects deduction immediately
          ...(isRefundedOrCancelled && order.affiliateCode
            ? { affiliateCommission: 0, affiliateCommissionAdjustment: 0 }
            : {}),
        };
      }
      const nextValue = field === "affiliateCommissionAdjustment" ? Number(value || 0) : value;
      if (field === "affiliateCommissionAdjustment") {
        supabasePayload = { affiliate_commission_adjustment: nextValue };
      }
      if (field === "trackingNumber") {
        const trimmed = String(value || "").trim();
        const sentAt = trimmed ? new Date().toISOString() : order.trackingNumberSentAt || "";
        supabasePayload = { tracking_number: trimmed, tracking_number_sent_at: sentAt };
        if (trimmed && order.email) {
          trackingEmailData = {
            email: order.email,
            orderId: order.id,
            trackingNumber: trimmed,
            firstName: order.firstName || "",
          };
        }
        return {
          ...order,
          trackingNumber: trimmed,
          trackingNumberSentAt: sentAt,
        };
      }
      if (field === "trackingNumber2") {
        const trimmed = String(value || "").trim();
        supabasePayload = { tracking_number_2: trimmed };
        if (trimmed && order.email) {
          trackingEmailData = {
            email: order.email,
            orderId: order.id,
            trackingNumber: trimmed,
            firstName: order.firstName || "",
          };
        }
        return { ...order, trackingNumber2: trimmed };
      }
      if (["firstName", "lastName", "address", "city", "postalCode", "state", "country", "phone", "taxId"].includes(field)) {
        const trimmed = String(value || "").trim();
        supabasePayload = { [field]: trimmed };
        return { ...order, [field]: trimmed };
      }
      if (field === "createdAt") {
        const iso = value ? new Date(value).toISOString() : order.createdAt || "";
        supabasePayload = { created_at: iso };
        return { ...order, createdAt: iso };
      }
      if (field === "invoiceId") {
        const trimmed = String(value || "").trim();
        supabasePayload = { invoice_id: trimmed };
        return { ...order, invoiceId: trimmed };
      }
      if (field === "paymentProvider") {
        const trimmed = String(value || "").trim();
        supabasePayload = { payment_provider: trimmed };
        return { ...order, paymentProvider: trimmed };
      }
      if (field === "paymentId") {
        const trimmed = String(value || "").trim();
        supabasePayload = { payment_id: trimmed };
        return { ...order, paymentId: trimmed };
      }
      if (field === "subtotal") {
        const num = Math.max(0, Number(value) || 0);
        supabasePayload = { subtotal: num };
        return { ...order, subtotal: num };
      }
      if (field === "shipping") {
        const num = Math.max(0, Number(value) || 0);
        supabasePayload = { shipping: num };
        return { ...order, shipping: num };
      }
      if (field === "storeCreditUsed") {
        const num = Math.max(0, Number(value) || 0);
        supabasePayload = { store_credit_used: num };
        return { ...order, storeCreditUsed: num };
      }
      if (field === "total") {
        const num = Math.max(0, Number(value) || 0);
        supabasePayload = { total: num };
        return { ...order, total: num };
      }
      if (field === "shippingType") {
        const trimmed = String(value || "standard").trim();
        supabasePayload = { shipping_type: trimmed };
        return { ...order, shippingType: trimmed };
      }
      if (field === "adminNote") {
        const trimmed = String(value || "").trim();
        adminNoteValue = trimmed; // handled separately — never touches a DB column
        return { ...order, adminNote: trimmed };
      }
      return {
        ...order,
        [field]: nextValue,
      };
    });
    saveStoredOrders(nextOrders);
    if (currentUser?.email) setUserOrders(getPaidOrdersForEmail(currentUser.email, nextOrders));
    setAdminMessage("Admin update saved.");
    window.clearTimeout(window.__tbvAdminMessageTimeout);
    window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 2500);

    if (supabasePayload) {
      persistOrderAdminFieldToSupabase(orderId, supabasePayload);
    }
    if (adminNoteValue !== null) {
      // Write admin note directly to metadata — avoids any DB column lookup
      (async () => {
        try {
          if (!String(orderId).startsWith("TEST-")) {
            const { data, error: readErr } = await supabase.from("orders").select("metadata").eq("id", orderId).single();
            if (readErr) throw new Error(readErr.message);
            const base = typeof data?.metadata === "object" && !Array.isArray(data.metadata) ? data.metadata : {};
            const { error: writeErr } = await supabase.from("orders").update({ metadata: { ...base, adminNote: adminNoteValue } }).eq("id", orderId);
            if (writeErr) throw new Error(writeErr.message);
          }
        } catch (err) {
          console.error("Failed to persist admin note:", err?.message || err);
        }
      })();
    }
    if (trackingEmailData) {
      sendTrackingEmail(trackingEmailData);
    }
  }

  async function deleteOrdersByEmail(email) {
    const target = String(email || "").trim().toLowerCase();
    if (!target) return;
    const matches = allOrders.filter((o) => String(o.email || "").trim().toLowerCase() === target);
    if (matches.length === 0) {
      window.alert(`No orders found for ${email}.`);
      return;
    }
    if (!window.confirm(`Delete all ${matches.length} order(s) placed with ${email}? This cannot be undone.`)) return;
    const ids = matches.map((o) => o.id);
    try {
      await supabase.from("orders").delete().in("id", ids);
    } catch (e) {
      console.error("Bulk delete orders error:", e);
    }
    try {
      await supabase.from("affiliate_orders").delete().in("order_id", ids);
    } catch (e) {
      console.error("Bulk delete affiliate_orders error:", e);
    }
    const deletedIds = new Set(JSON.parse(localStorage.getItem("tbv-deleted-order-ids") || "[]"));
    ids.forEach((id) => deletedIds.add(id));
    localStorage.setItem("tbv-deleted-order-ids", JSON.stringify([...deletedIds]));
    const next = getStoredOrders().filter((o) => !ids.includes(o.id));
    localStorage.setItem("tbv-orders", JSON.stringify(next));
    setAllOrders((prev) => prev.filter((o) => !ids.includes(o.id)));
    await loadOrdersFromSupabase();
  }

  async function deleteAdminOrder(orderId) {
    if (!window.confirm("Delete this order permanently? This cannot be undone.")) return;
    try {
      await supabase.from("orders").delete().eq("id", orderId);
    } catch (e) {
      console.error("Delete order error:", e);
    }
    // Also remove affiliate commission record so affiliate panel stays in sync
    try {
      await supabase.from("affiliate_orders").delete().eq("order_id", orderId);
    } catch (e) {
      console.error("Delete affiliate_orders error:", e);
    }
    // Persist deleted ID so it stays hidden even after Supabase reload
    const deletedIds = JSON.parse(localStorage.getItem("tbv-deleted-order-ids") || "[]");
    if (!deletedIds.includes(orderId)) deletedIds.push(orderId);
    localStorage.setItem("tbv-deleted-order-ids", JSON.stringify(deletedIds));
    const next = getStoredOrders().filter((o) => o.id !== orderId);
    localStorage.setItem("tbv-orders", JSON.stringify(next));
    setAllOrders(next);
  }

  async function updateOrderItemsAdmin(orderId, newItems) {
    const orders = getStoredOrders();
    const existingOrder = orders.find((o) => o.id === orderId);
    const shipping = Number(existingOrder?.shipping || 0);
    const storeCreditUsed = Number(existingOrder?.storeCreditUsed || 0);
    const newSubtotal = newItems.reduce((sum, item) => sum + (Number(item.price || 0) * Number(item.quantity || item.qty || 1)), 0);
    const newTotal = Math.max(0, newSubtotal + shipping - storeCreditUsed);
    const nextOrders = orders.map((o) => o.id !== orderId ? o : { ...o, items: newItems, subtotal: newSubtotal, total: newTotal });
    saveStoredOrders(nextOrders);
    if (currentUser?.email) setUserOrders(getPaidOrdersForEmail(currentUser.email, nextOrders));
    setAdminMessage("Items updated.");
    window.clearTimeout(window.__tbvAdminMessageTimeout);
    window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 2000);
    if (String(orderId).startsWith("TEST-")) return;
    try {
      const { data, error: readErr } = await supabase.from("orders").select("metadata").eq("id", orderId).single();
      if (readErr) throw new Error(readErr.message);
      const baseMeta = typeof data?.metadata === "object" && !Array.isArray(data.metadata) ? data.metadata : {};
      const { error: writeErr } = await supabase.from("orders").update({
        metadata: { ...baseMeta, items: newItems, subtotal: newSubtotal, total: newTotal },
        total: newTotal,
      }).eq("id", orderId);
      if (writeErr) throw new Error(writeErr.message);
    } catch (err) {
      console.error("Failed to update order items in Supabase:", err?.message || err);
      setAdminMessage(`Sync failed: ${err?.message || "unknown error"}`);
      window.clearTimeout(window.__tbvAdminMessageTimeout);
      window.__tbvAdminMessageTimeout = window.setTimeout(() => setAdminMessage(""), 5000);
    }
  }


