  const tx = (en, ru, ua, de, es) => {
    if (language === "RU") return ru ?? en;
    if (language === "UA") return ua ?? en;
    if (language === "DE") return de ?? deText[en] ?? en;
    if (language === "ES") return es ?? esText[en] ?? en;
    return en;
  };

  async function copySupportEmail() {
    const email = "SUPPORT@10BOTTLEVALUE.CO";

    try {
      if (navigator?.clipboard?.writeText && window.isSecureContext) {
        await navigator.clipboard.writeText(email);
      } else if (!fallbackCopyText(email)) {
        return;
      }

      setCopiedEmail(true);
      window.clearTimeout(window.__tbvCopyEmailTimeout);
      window.__tbvCopyEmailTimeout = window.setTimeout(
        () => setCopiedEmail(false),
        1800
      );
    } catch {
      if (fallbackCopyText(email)) {
        setCopiedEmail(true);
        window.clearTimeout(window.__tbvCopyEmailTimeout);
        window.__tbvCopyEmailTimeout = window.setTimeout(
          () => setCopiedEmail(false),
          1800
        );
      }
    }
  }

