      city: syncedCF.city || "",
      state: syncedCF.state || "",
      postalCode: syncedCF.postalCode || "",
      phone: syncedCF.phone || "",
        taxId: syncedCF.taxId || "",
        orderNotes: getCheckoutOrderNotes(syncedCF),
